"""Generate the public AZ Reborn map reference used by the tracker."""
import argparse
import json
from pathlib import Path


def generate(source: Path, target: Path) -> None:
    zones = json.loads(source.read_text(encoding="utf-8"))
    keys = {zone["key"] for zone in zones}
    assert len(keys) == len(zones) and "naxx" in keys
    lines = [
        "-- Generated by scripts/generate_reborn_maps.py.",
        "-- Source: https://azreborn.com/data/v1/zones.json (public Data API v1).",
        "-- Each row: health and late factors, final and first boss base HP and hit,",
        "-- then campaign page and the standard drop tier (including explicit overrides).",
        "SurvivorUI_RebornMapReference = {",
    ]
    pairs = ("common", "uncommon", "rare", "epic", "pvp", "legendary")
    positions = {}
    for zone in sorted(zones, key=lambda entry: entry["order"]):
        final, = [boss for boss in zone["bosses"] if boss["final"]]
        first = zone["bosses"][0]
        values = [zone["health_factor"], zone["late_factor"], final["health"], final["damage"],
                  first["health"], first["damage"]]
        assert all(type(value) in (int, float) and 0 <= value < 10**10 for value in values)
        page = zone["page"]
        position = positions.get(page, 0)
        positions[page] = position + 1
        rarity = zone["gear_rarity"] or pairs[position // 2]
        lines.append("\t[" + json.dumps(zone["key"], ensure_ascii=True) + "] = { "
                     + ", ".join([*map(str, values), str(page), json.dumps(rarity)]) + " },")
    target.write_text("\n".join([*lines, "}", ""]), encoding="utf-8", newline="\n")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("snapshot", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    generate(args.snapshot, args.output)
